"""PL-03 step 3: maximum drawdown per ticker (spine: depth only, dates at `base_date`)."""

from __future__ import annotations

import math
from dataclasses import dataclass
from itertools import accumulate

from risk.types import Returns


@dataclass(frozen=True)
class Drawdown:
    """The deepest fall below the running peak: `depth` ≤ 0, `peak_date` ≤ `trough_date`."""

    ticker: str
    depth: float
    peak_date: str
    trough_date: str

    def __post_init__(self) -> None:
        if not self.depth <= 0:
            raise ValueError(f"{self.ticker}: depth must be at most 0")
        if self.peak_date > self.trough_date:
            raise ValueError(f"{self.ticker}: peak_date must not come after trough_date")


def max_drawdown(returns: Returns) -> tuple[Drawdown, ...]:
    """One drawdown per ticker, wealth starting at 1 on `base_date`; the spine dates both ends there."""
    drawdowns = []
    for ticker in returns.tickers:
        wealth = [1.0, *(math.exp(total) for total in accumulate(returns.values[ticker]))]
        depth = min(value / peak - 1 for value, peak in zip(wealth, accumulate(wealth, max)))
        drawdowns.append(
            Drawdown(
                ticker=ticker,
                depth=depth,
                peak_date=returns.base_date,
                trough_date=returns.base_date,
            )
        )
    return tuple(drawdowns)

