"""PL-03 step 4: write the JSON risk report, one row per ticker, sorted."""

from __future__ import annotations

import json
from collections.abc import Mapping, Sequence
from dataclasses import asdict, dataclass
from pathlib import Path

from risk.drawdown import Drawdown
from risk.summary import TickerSummary


@dataclass(frozen=True)
class Report:
    """The written report: `rows` are the file's rows, one per ticker, sorted."""

    path: str
    rows: tuple[Mapping[str, object], ...]

    def __post_init__(self) -> None:
        tickers = [str(row["ticker"]) for row in self.rows]
        if tickers != sorted(set(tickers)):
            raise ValueError("rows must be one per ticker, sorted")


def write_report(
    summary: Sequence[TickerSummary], drawdowns: Sequence[Drawdown], out_path: str | Path
) -> Report:
    """Write `{"tickers": [...]}` to `out_path`: each summary with its drawdown as `max_drawdown`."""
    by_ticker = {drawdown.ticker: drawdown for drawdown in drawdowns}
    if sorted(by_ticker) != sorted(item.ticker for item in summary):
        raise ValueError("summary and drawdowns must cover the same tickers")
    rows = tuple(
        {
            **asdict(item),
            "max_drawdown": by_ticker[item.ticker].depth,
            "peak_date": by_ticker[item.ticker].peak_date,
            "trough_date": by_ticker[item.ticker].trough_date,
        }
        for item in sorted(summary, key=lambda item: item.ticker)
    )
    report = Report(path=str(out_path), rows=rows)
    Path(out_path).write_text(json.dumps({"tickers": rows}, indent=2, allow_nan=False) + "\n")
    return report

